SELECT u.id,u.username,u.first_name,u.photo_url,u.role,u.language,u.theme,u.ban_until,u.created_at,u.updated_at,count(d.id),max(d.created_at) FROM users u LEFT JOIN download_log d ON d.user_id=u.id AND (?4='0' OR d.created_at >= CAST(unixepoch('subsec')*1000000 AS INTEGER)-CAST(?4 AS INTEGER)*86400000000) WHERE (?1='' OR lower(coalesce(u.username,'')) LIKE '%'||lower(ltrim(?1,'@'))||'%' OR lower(coalesce(u.first_name,'')) LIKE '%'||lower(?1)||'%') AND (?2='all' OR u.role=?2) AND (?3='all' OR (?3='active' AND u.role NOT IN ('restricted','banned') AND (u.ban_until IS NULL OR u.ban_until <= CAST(unixepoch('subsec')*1000000 AS INTEGER))) OR (?3='restricted' AND u.role='restricted') OR (?3='banned' AND (u.role='banned' OR u.ban_until > CAST(unixepoch('subsec')*1000000 AS INTEGER)))) GROUP BY u.id ORDER BY u.updated_at DESC,u.id DESC LIMIT ?6 OFFSET ?5;